import 'dart:io';import 'package:csv/csv.dart';import 'package:file_picker/file_picker.dart';import 'package:path/path.dart' as p;import 'package:path_provider/path_provider.dart';import 'package:share_plus/share_plus.dart';import 'package:uuid/uuid.dart';import '../data/app_database.dart';import '../data/product.dart';
class CsvService {
 static const headers=['product_name','barcode','brand','category','front_image','back_image','ingredients_image'];
 static Future<String> exportDataset(String id,String name) async{final products=await AppDatabase.instance.products(id);final rows=<List<dynamic>>[headers,...products.map((x)=>[x.name,x.barcode,x.brand,x.category,x.frontImage,x.backImage,x.ingredientsImage])];final content=const ListToCsvConverter().convert(rows);final dir=await getApplicationDocumentsDirectory();final file=File(p.join(dir.path,'${_safeName(name)}_${DateTime.now().millisecondsSinceEpoch}.csv'));await file.writeAsString('\uFEFF$content',flush:true);return file.path;}
 static Future<void> shareCsv(String id,String name) async{final path=await exportDataset(id,name);await Share.shareXFiles([XFile(path)],text:'مجموعة المنتجات: $name');}
 static Future<String> importCsv(String id) async{final picked=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['csv'],withData:true);if(picked==null||picked.files.isEmpty)return 'تم إلغاء الاستيراد';final f=picked.files.first;final bytes=f.bytes??(f.path!=null?await File(f.path!).readAsBytes():null);if(bytes==null)return 'تعذّر قراءة الملف';final text=String.fromCharCodes(bytes).replaceFirst('\uFEFF','');final rows=const CsvToListConverter(shouldParseNumbers:false).convert(text);if(rows.isEmpty)return 'الملف فارغ';final h=rows.first.map((e)=>e.toString().trim().toLowerCase()).toList();int idx(List<String> a)=>h.indexWhere(a.contains);final ni=idx(['product_name','name','اسم المنتج','الاسم']),bi=idx(['barcode','باركود','الباركود']),bri=idx(['brand','العلامة التجارية','الشركة']),ci=idx(['category','الفئة','التصنيف']);if(ni<0)return 'عمود اسم المنتج غير موجود';final now=DateTime.now().toIso8601String();int count=0;for(final row in rows.skip(1)){String v(int i)=>i>=0&&i<row.length?row[i].toString().trim():'';final name=v(ni),barcode=bi<0?'':v(bi);if(name.isEmpty)continue;final old=barcode.isEmpty?null:await AppDatabase.instance.productByBarcode(id,barcode);await AppDatabase.instance.saveProduct(Product(id:old?.id??const Uuid().v4(),datasetId:id,name:name,barcode:barcode,brand:v(bri),category:v(ci),frontImage:'',backImage:'',ingredientsImage:'',createdAt:old?.createdAt??now,updatedAt:now));count++;}return 'تم استيراد $count منتج';}
 static String _safeName(String s)=>s.replaceAll(RegExp(r'[^\\w\\u0600-\\u06FF-]+'),'_');
}
